// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    function setUp() public { c = new PoCGame(address(this), 0); }
    function testRegression_property() public {
        c.OpenToThePublic();
        c.AdjustBetAmounts(100);

        address contractCaller = address(new ContractCaller());
        vm.deal(contractCaller, 100 ether);
        vm.prank(contractCaller);

        (bool success,) = address(c).call{value: 100}(abi.encodeWithSignature("wager()"));

        assertTrue(success == false);
    }
}

contract ContractCaller {
    fallback() external payable {}
}
